            return "no checkpoint found, continuing with the local files"
        done, _, gen_dir, manifest, store = max(found, key=lambda c: c[:2])
        if manifest["fingerprint"] != self.fingerprint:
            raise CheckpointError(
                f"{store.label} holds a checkpoint of a different run (inputs / --limit-videos / output name differ). "
                "Use another --run-name, or the same inputs and options."
            )
